/* Midnight Bloom Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="midnight-bloom-light"] {
  --background: rgb(248, 248, 248);
  --foreground: rgb(51, 51, 51);
  --card: rgb(255, 255, 255);
  --card-foreground: rgb(51, 51, 51);
  --popover: rgb(255, 255, 255);
  --popover-foreground: rgb(51, 51, 51);
  --primary: rgb(109, 93, 231);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(162, 200, 240);
  --secondary-foreground: rgb(51, 51, 51);
  --muted: rgb(201, 196, 182);
  --muted-foreground: rgb(111, 111, 111);
  --accent: rgb(140, 148, 107);
  --accent-foreground: rgb(255, 255, 255);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(212, 212, 212);
  --input: rgb(212, 212, 212);
  --ring: rgb(109, 93, 231);
  --chart-1: rgb(109, 93, 231);
  --chart-2: rgb(143, 69, 174);
  --chart-3: rgb(75, 0, 131);
  --chart-4: rgb(99, 148, 235);
  --chart-5: rgb(70, 131, 181);
  --radius: 0.5rem;
  --sidebar: rgb(248, 248, 248);
  --sidebar-foreground: rgb(51, 51, 51);
  --sidebar-primary: rgb(109, 93, 231);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(140, 148, 107);
  --sidebar-accent-foreground: rgb(255, 255, 255);
  --sidebar-border: rgb(212, 212, 212);
  --sidebar-ring: rgb(109, 93, 231);
  --font-sans: Montserrat, sans-serif;
  --font-serif: Playfair Display, serif;
  --font-mono: Source Code Pro, monospace;
  --shadow-color: rgb(0, 0, 0);
  --shadow-opacity: 0.1;
  --shadow-blur: 10px;
  --shadow-spread: -2px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 5px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 5px 10px -2px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 1px 2px -3px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 2px 4px -3px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 4px 6px -3px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 5px 10px -2px hsl(0 0% 0% / 0.1), 0px 8px 10px -3px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 5px 10px -2px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

