  --primary: rgb(109, 93, 231);
  --primary-foreground: rgb(255, 255, 255);
  --secondary: rgb(75, 0, 131);
  --secondary-foreground: rgb(228, 228, 228);
  --muted: rgb(69, 69, 69);
  --muted-foreground: rgb(164, 164, 164);
  --accent: rgb(99, 148, 235);
  --accent-foreground: rgb(228, 228, 228);
  --destructive: rgb(241, 68, 68);
  --destructive-foreground: rgb(255, 255, 255);
  --border: rgb(69, 69, 69);
  --input: rgb(69, 69, 69);
  --ring: rgb(109, 93, 231);
  --chart-1: rgb(109, 93, 231);
  --chart-2: rgb(143, 69, 174);
  --chart-3: rgb(75, 0, 131);
  --chart-4: rgb(99, 148, 235);
  --chart-5: rgb(70, 131, 181);
  --radius: 0.5rem;
  --sidebar: rgb(27, 29, 34);
  --sidebar-foreground: rgb(228, 228, 228);
  --sidebar-primary: rgb(109, 93, 231);
  --sidebar-primary-foreground: rgb(255, 255, 255);
  --sidebar-accent: rgb(99, 148, 235);
  --sidebar-accent-foreground: rgb(228, 228, 228);
  --sidebar-border: rgb(69, 69, 69);
  --sidebar-ring: rgb(109, 93, 231);
  --font-sans: Montserrat, sans-serif;
  --font-serif: Playfair Display, serif;
  --font-mono: Source Code Pro, monospace;
  --shadow-color: rgb(0, 0, 0);
